```c
static const uint8_t sbox[256] = {...};
static const uint8_t rcon[10] = {0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0x1b, 0x36};

void aes_key_expand(const uint8_t* key, int key_len, uint8_t* round_keys, int* nr) {
    int nk = key_len / 4; // 4, 6, 8
    *nr = nk + 6; // 10, 12, 14
    int nb = 4;
    int total_words = nb * (*nr + 1);
    uint32_t w[60];
    for (int i = 0; i < nk; i++)
        w[i] = (key[4*i] << 24) | (key[4*i+1] << 16) | (key[4*i+2] << 8) | key[4*i+3];
    for (int i = nk; i < total_words; i++) {
        uint32_t temp = w[i-1];
        if (i % nk == 0) {
            temp = subword(rotword(temp)) ^ (rcon[i/nk - 1] << 24);
        } else if (nk > 6 && i % nk == 4) {
            temp = subword(temp);
        }
        w[i] = w[i-nk] ^ temp;
    }
    // copy to round_keys as bytes
    for (int i = 0; i < total_words; i++) {
        round_keys[4*i] = w[i] >> 24;
        round_keys[4*i+1] = w[i] >> 16;
        round_keys[4*i+2] = w[i] >> 8;
        round_keys[4*i+3] = w[i];
    }
}
```

