#include <wmmintrin.h>
#include <emmintrin.h>
#include <smmintrin.h>
#include <immintrin.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

static inline __m128i key_expand(__m128i key, __m128i keygened) {
    keygened = _mm_shuffle_epi32(keygened, _MM_SHUFFLE(3,3,3,3));
    key = _mm_xor_si128(key, _mm_slli_si128(key, 4));
    key = _mm_xor_si128(key, _mm_slli_si128(key, 4));
    key = _mm_xor_si128(key, _mm_slli_si128(key, 4));
    return _mm_xor_si128(key, keygened);
}

static void aes128_key_schedule(const uint8_t *key, __m128i rk[11]) {
    rk[0] = _mm_loadu_si128((const __m128i*)key);
    static const int rcon[10] = {1,2,4,8,16,32,64,128,27,54};
    __m128i temp = rk[0];
    for (int i = 1; i < 11; i++) {
        temp = key_expand(temp, _mm_aeskeygenassist_si128(temp, rcon[i-1]));
        rk[i] = temp;
    }
}

static inline __m128i aes_enc(__m128i s, const __m128i rk[11]) {
    s = _mm_xor_si128(s, rk[0]);
    s = _mm_aesenc_si128(s, rk[1]);
    s = _mm_aesenc_si128(s, rk[2]);
    s = _mm_aesenc_si128(s, rk[3]);
    s = _mm_aesenc_si128(s, rk[4]);
    s = _mm_aesenc_si128(s, rk[5]);
    s = _mm_aesenc_si128(s, rk[6]);
    s = _mm_aesenc_si128(s, rk[7]);
    s = _mm_aesenc_si128(s, rk[8]);
    s = _mm_aesenc_si128(s, rk[9]);
    return _mm_aesenclast_si128(s, rk[10]);
}

// CTR encrypt: counter starts at ctr0 (16 bytes), increments by 1 each block
static void ctr_encrypt(const uint8_t *in, uint8_t *out, size_t nbytes, __m128i ctr0, const __m128i rk[11]) {
    size_t nblocks = nbytes / 16;
    __m128i ctr = ctr0;
    for (size_t i = 0; i < nblocks; i++) {
        __m128i ks = aes_enc(ctr, rk);
        __m128i pt = _mm_loadu_si128((const __m128i*)(in + i*16));
        __m128i ct = _mm_xor_si128(pt, ks);
        _mm_storeu_si128((__m128i*)(out + i*16), ct);
        // increment counter (big-endian 128-bit)
        ctr = _mm_add_epi64(ctr, _mm_set_epi64x(0, 1));
        // handle carry from low 64 to high 64
        // (for our sizes, low 32 bits won't overflow 64, so this is fine)
    }
    // handle remainder
    size_t rem = nbytes % 16;
    if (rem) {
        __m128i ks = aes_enc(ctr, rk);
        uint8_t ksbuf[16];
        _mm_storeu_si128((__m128i*)ksbuf, ks);
        for (size_t j = 0; j < rem; j++) out[nblocks*16 + j] = in[nblocks*16 + j] ^ ksbuf[j];
    }
}

int main() {
    size_t n = 60000ULL * 1024;
    uint8_t *in = malloc(n);
    uint8_t *out = malloc(n);
    uint8_t key[16] = {0};
    uint8_t nonce[12] = {0};
    for (size_t i = 0; i < n; i++) in[i] = (uint8_t)(i * 7 + 1);

    __m128i rk[11];
    aes128_key_schedule(key, rk);

    // J0 = nonce || 0x00000001, first counter = nonce || 0x00000002
    uint8_t ctr0buf[16];
    memcpy(ctr0buf, nonce, 12);
    ctr0buf[12] = 0; ctr0buf[13] = 0; ctr0buf[14] = 0; ctr0buf[15] = 2;
    __m128i ctr0 = _mm_loadu_si128((__m128i*)ctr0buf);

    // warmup
    ctr_encrypt(in, out, n, ctr0, rk);

    int iters = 20;
    struct timespec t0, t1;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    for (int i = 0; i < iters; i++) {
        ctr_encrypt(in, out, n, ctr0, rk);
    }
    clock_gettime(CLOCK_MONOTONIC, &t1);
    double dt = (t1.tv_sec - t0.tv_sec) + (t1.tv_nsec - t0.tv_nsec)/1e9;
    double gbps = (double)n * iters / dt / 1e9;
    printf("CTR: %.2f GB/s, %.2f ms per 61MB\n", gbps, (double)n/dt/1e6);
    return 0;
}
